import{_ as e,o as a,c as t,ag as _}from"./chunks/framework.DaAXJYxM.js";const m=JSON.parse('{"title":"第39章 排名","description":"","frontmatter":{},"headers":[],"relativePath":"第39章_排名.md","filePath":"第39章_排名.md"}'),r={name:"第39章_排名.md"};function o(n,p,s,c,i,d){return a(),t("div",null,[...p[0]||(p[0]=[_('<h1 id="第39章-排名" tabindex="-1">第39章 排名 <a class="header-anchor" href="#第39章-排名" aria-label="Permalink to &quot;第39章 排名&quot;">​</a></h1><p>四月末，一模的成绩贴出来了。</p><p>不是全校贴，是年级在后墙贴了一张表，前一百个名字。</p><p>那天下午下课我走过去看。人挤得多，我在外面等着，等散了一点才往前。</p><p>我从上往下看。</p><p>看到第六十几的时候看见自己的名字。</p><p>我站在那里看了大概半分钟。前面那个人回头问我找谁。我说没找谁。</p><p>我回教室的路上，心里想的第一件事不是给我妈打电话。</p><p>我想的是告诉她。</p><p>那天晚上她上线了。</p><p>她上线的第一句话是这个。</p><p>她说：你帮我看看。</p><p>后面跟着一张图。是一个小东西，塑料的，边上有一道很细的白痕。</p><p>她说，这个人说这是运输划痕，可以赔十五。</p><p>她说，我觉得是出厂就有的。</p><p>我说，你把它对着灯看一下，看那道痕是在膜上还是在料上。</p><p>她说，怎么看。</p><p>我说，把灯关了，举到窗外，让光斜着过去。</p><p>她过了两分钟发了一张照片过来。黑乎乎的，什么都看不清。</p><p>她说，看不见。</p><p>我说，你手抖。</p><p>她说，风大。</p><p>我说，你在哪吹风。</p><p>她说，阳台上。</p><p>她说，我不敢在屋里弄。</p><p>那天晚上我们讨论了二十分钟那道划痕。</p><p>中间她说那个人不回她，说要视频。她说她录了，录完发过去，对方说看不出来。她说你听听这是人话吗。</p><p>我说，那你退。</p><p>她说，退了我要等三个月。</p><p>我说，那是有点久。</p><p>她说，而且这批过了就没了。</p><p>我说，那你就留着。</p><p>她说，那我亏了十五块。</p><p>我说，你没亏，你只是少赚。</p><p>她说，你这话说的，好像我拿它做生意。</p><p>我说，你不是在做么。</p><p>她说，我就是出几个多余的。</p><p>她说，我不赚钱，我就是不想便宜那个卖家。</p><p>那天我们算了很久，最后她说明天我去问他要视频，他不给就退。</p><p>我说好。</p><p>然后她问我，你今天怎么样。</p><p>我说，还行。</p><p>她说，你是不是有事。</p><p>我说，没有。</p><p>她说，说。</p><p>我说，排名出来了，我在前一百。</p><p>她隔了很久没回。</p><p>隔了很久之后回了一句。</p><p>她说，哦，那挺好。</p><p>我说，嗯。</p><p>她说，我就说你最近不说话是因为这个。</p><p>我说，不是。</p><p>她说，那是什么。</p><p>我说，没什么。</p><p>那天晚上她十一点多下线了。下线之前说她要睡了，明天还要早起。</p><p>我说好。</p><p>我坐在床上，把那三个字在心里翻了很多遍。</p><p>那挺好。</p><p>我不知道该怎么想这件事。</p><p>三个月前她问我，你有没有想我。我说我数你一天发几条消息。她说你有病。我说你也差不多。那一次我们两个笑了很久。</p><p>现在她看到我考进了前一百，她说那挺好。</p><p>那天晚上我在本子上写了一句：她把这句话说明白了。</p><p>写完自己都看不懂。我划掉，重新写。</p><p>我写：我考进了前一百，我第一个想告诉的人是她。她回了一句那挺好。</p><p>写完想了想，又补了半句。</p><p>我补的是：她没有问我难不难。</p><p>五月初的两天，她上线一次，说的还是谷子的事。</p><p>那个人不肯赔，她说她要挂出去让别人评评理。</p><p>她说，你别笑，我是有道理的。</p><p>我说，我不笑。</p><p>她说，你肯定在心里笑。</p><p>我说，我在帮你算。</p><p>她说，算啥。</p><p>我说，算你要不要为这个再熬一个晚上。</p><p>她隔了很久，回了一个字：要。</p><p>那天晚上她熬到两点。她真的挂出去了。</p><p>第二天她跟我说，有三十几个人站她。</p><p>她说，你看。</p><p>我说，我看到了。</p><p>她说，我说的对吧。</p><p>我说，你说的对。</p><p>那一天我很高兴。</p><p>我高兴的是她那天上线了很久，久到我忘了数时间。</p><p>我把这两件事混在一起，一直到五月才分开。</p><p>分开了我才明白：她那几天需要的是一个帮她算账、帮她看划痕、帮她数有没有人站她的工具。</p><p>工具是随叫随到的。</p><p>所以我该高兴。</p><p>那几天我做题做得很稳，稳到周奕说你怎么像换了个人。我说想通了。</p><p>他说不怪你，前面一百名不是谁都上得去的。</p><p>我说，不是因为这个。</p><p>他说，那是因为什么。</p><p>我说，没什么。</p><p>他看了我一眼，把笔袋收了，走了。</p><p>那个月我第一次有一个念头：我这辈子可能就是这样，把她的事办得很好，把我的话留到很晚。</p><p>这个念头我在心里存了两年。</p><p>过了两天，我跟沈聿提了一次。</p><p>那天我们在操场边上坐着，他拿一支笔在地上划。</p><p>我说，问你一件事。</p><p>他说，讲。</p><p>我说，一个人考进了前一百，另一个人跟他说那挺好。这是什么意思。</p><p>他抬头看了我一眼。</p><p>他说，你直接说名字。</p><p>我说，我就是想知道这句算什么。</p><p>他把笔在地上划了一下，想了一会儿。</p><p>他说，这句算接住了。</p><p>我说，接住？</p><p>他说，他想告诉你他听见了，可他不知道接什么，所以接一句不冷不热的。</p><p>他说，这不算坏。</p><p>我坐在那里没说话。</p><p>他说，你想要什么。</p><p>我说，我想她问我一句难不难。</p><p>沈聿把笔拿起来，看了我一会儿。</p><p>他说，那你可以直接说。</p><p>我说，说不出口。</p><p>他说，那你下次想听她问，你今天得先问她事。</p><p>我说，什么。</p><p>他说，关系不是这么用的。你想得一句问话，你得先给一句。</p><p>那天我回宿舍，把这句话写在本子上。</p><p>我写：关系不是这么用的。</p><p>这一句我留了三年。</p><p>三年以后我才明白，它不只是说关系的，它是说我的。</p><p>我一直想要一句我没给过的东西。</p><p>那天晚上我把这件事做了。</p><p>我给她发了一句：我今天排名出来了。</p><p>其实我已经说过了。</p><p>可我想再看一次她怎么回。</p><p>她隔了一会儿回：嗯，看到了。</p><p>我说，你就不能说点别的。</p><p>她说，说什么。</p><p>我说，你说一句恭喜。</p><p>她隔了很久。</p><p>隔到我以为她不会回了。</p><p>然后她回了一句。</p><p>她说，恭喜。</p><p>后面跟了一个[鼓掌]。</p><p>那个表情很大，占了一整行，白手，红手指。</p><p>我看着那个表情，不知道该不该笑。</p><p>我说，就这样？</p><p>她说，你要哪样。</p><p>我说，我不知道。</p><p>她说，你不知道你要哪样，那你问我干嘛。</p><p>那天夜里我把这句话拄在本子上。</p><p>我拄完才发现她说得对。</p><p>我不知道我要哪样。</p>',144)])])}const f=e(r,[["render",o]]);export{m as __pageData,f as default};
